public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    CustVendExternalItem lCustVendExternalItem;
    ItemId currentItemId = this.ItemId;

    super(_entityCtx, _dataSourceCtx);

    if(_entityCtx.isDatabaseOperationInsert() || _entityCtx.isDatabaseOperationUpdate())
    {
        lCustVendExternalItem = _dataSourceCtx.getBuffer();
        lCustVendExternalItem.InventDimId = 'AllBlank';
        lCustVendExternalItem.ModuleType = ModuleInventPurchSalesVendCustGroup::Vend;
    }
    this.checkNeedsMapping();
}

/// <summary>
/// Checks if mapping between the intercompany items is needed
/// </summary>
/// <returns>true or false</returns>
private boolean checkNeedsMapping(boolean _throwError = true)
{
    InventTable lInventTable, externalInventTable;
    RecId productRecId, externalProductRecId;

    ItemId itemId =  this.ItemId;
    ItemId externalItemId =  this.ExternalItemId;

    boolean needsMapping = true;

    productRecId = InventTable::find(itemId).Product;
    DataAreaId dataAreaId = NDXHelperItem::DataAreaIdFromItemId(externalItemId);

    if(dataAreaId)
    {
        changecompany(dataAreaId)
        {
            externalProductRecId = InventTable::find(externalItemId).Product;
        }
    }

    needsMapping = productRecId && externalProductRecId && productRecId != externalProductRecId;

    if(productRecId && externalProductRecId &&!needsMapping && _throwError)
    {
        throw error(strFmt("@NDX:NDXCustVendExternalItemEntityInfo", this.ItemId, this.ExternalItemId));
    }

    return needsMapping;
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    CustVendExternalItem lCustVendExternalItem;

    boolean ret;
    ret = super(_entityCtx, _dataSourceCtx);

    //If mapping not needed then delete the record
    if(ret && !this.checkNeedsMapping(false))
    {
        delete_from lCustVendExternalItem
            where lCustVendExternalItem.ItemId == this.ItemId
            && lCustVendExternalItem.CustVendRelation == this.CustVendRelation;

    }

    return ret;
}
